import fs from "node:fs"
import path from "node:path"

const MONOGRAPHS = {
  // Category 1: Tissue Repair
  "bpc-157": "BPC-157 (Body Protection Compound-157) is a synthetic 15-amino-acid pentadecapeptide derived from a native gastric juice protective protein sequence. In cellular and molecular biology assays, BPC-157 operates as a pleiotropic cytoprotective and tissue reparative agent. Mechanistically, it triggers the transcriptional upregulation of early growth response-1 (egr-1) and vascular endothelial growth factor receptor 2 (VEGFR2/Flk-1), leading to focal adhesion kinase (FAK) and paxillin phosphorylation. This molecular cascade stimulates directed endothelial cell migration, microvascular sprout formation, and capillary tubule stabilization. Concurrently, BPC-157 modulates endothelial nitric oxide synthase (eNOS) activation, maintaining balanced nitric oxide production without inducing systemic hypotension. In musculoskeletal explant cultures, BPC-157 promotes rapid collagen type I synthesis, tendon outgrowth, and tenocyte migration across mechanically injured tissue substrates.",
  "tb-500": "TB-500 is a synthetic peptide containing the active 43-amino-acid sequence of Thymosin Beta-4 (specifically featuring the essential actin-binding hexapeptide motif Ac-LKKTETQ). In cellular biology, Thymosin Beta-4 is the principal intracellular G-actin sequestering molecule, regulating actin polymerization dynamics and cytoskeletal reorganization. Extracellularly, TB-500 promotes rapid lamellipodia formation, cell motility, and directed migration of endothelial cells, keratinocytes, and dermal fibroblasts. Downstream signaling studies demonstrate that TB-500 stimulates the PI3K/Akt pathway and upregulates matrix metalloproteinases (specifically MMP-2 and MMP-9), facilitating extracellular matrix remodeling and tissue extravasation. Furthermore, TB-500 downregulates nuclear factor kappa B (NF-κB) transcription, reducing cytotoxic inflammatory signaling and secondary fibrotic tissue remodeling across wound healing and ischemic models.",
  "ghk-cu": "GHK-Cu is a high-affinity tripeptide copper complex (Glycyl-L-Histidyl-L-Lysine Cu2+) naturally present in human plasma. As a transcriptional regulator and epigenetic modulator, GHK-Cu resets gene expression patterns across more than 4,000 human genes toward a regenerative, anti-inflammatory profile. It binds specific cell surface receptors and facilitates receptor-mediated copper transport into cytosolic metallochaperones. Mechanistically, GHK-Cu stimulates the expression of decorin and small leucine-rich proteoglycans, upregulates collagen types I, III, and IV, and increases elastin and glycosaminoglycan synthesis in dermal fibroblasts. Simultaneously, it modulates tissue remodeling by equilibrating matrix metalloproteinases (MMP-1, MMP-2) and tissue inhibitors of metalloproteinases (TIMP-1, TIMP-2), preventing hypertrophic scar formation while stimulating capillary angiogenesis via basic fibroblast growth factor (bFGF).",
  "ghk-basic": "GHK-Basic (Glycyl-L-Histidyl-L-Lysine free base) is the non-chelated parent tripeptide fragment of the endogenous GHK signaling system. In laboratory assays, GHK-Basic serves as an analytical reference standard and bioactive matrikine. It interacts with cellular integrins and surface glycosaminoglycans, stimulating procollagen synthesis and dermal extracellular matrix turnover independent of exogenous transition metal ions. In vitro research demonstrates that GHK-Basic enhances cellular stemness markers, increases epidermal keratinocyte proliferation, and downregulates pro-apoptotic caspase cascades in oxidative stress environments. Its unchelated formulation allows researchers to perform controlled stoichiometry assays, titration of specific divalent metal ions (including copper, zinc, and iron), and baseline evaluation of metallopeptide enzymatic activity.",
  "kpv": "KPV (Lysine-Proline-Valine) is a biologically active C-terminal tripeptide fragment of alpha-melanocyte-stimulating hormone (alpha-MSH). Operating independently of classical melanocortin 1 receptor (MC1R) pigmentation signaling, KPV functions as a potent nuclear-targeted anti-inflammatory modulator. Cellular research shows that KPV directly translocates across the plasma membrane into the cytoplasm and nucleus via non-endocytic mechanisms. Inside the cell, KPV inhibits the nuclear translocation of NF-κB (specifically the p65/p50 heterodimer), blocking the transcription of pro-inflammatory cytokines including TNF-alpha, IL-1beta, IL-6, and IL-8. In epithelial and mucosal barrier models, KPV upregulates tight junction proteins (zonula occludens-1, occludin), mitigating paracellular hyperpermeability and counteracting bacterial lipopolysaccharide (LPS)-induced enterocyte apoptosis.",
  "ara-290": "ARA-290 (Cibinetide) is an engineered 11-amino-acid peptide modeled after the spatial beta-hairpin domain of erythropoietin (helix B). Unlike full-length erythropoietin, ARA-290 possesses zero binding affinity for the classical homodimeric EPO receptor (EPOR2), completely eliminating hematocrit elevation, erythrogenesis, or thrombotic cascades. Instead, ARA-290 selectively and potently binds the heteromeric Innate Repair Receptor (IRR), a complex composed of EPOR and the common beta-subunit CD131 (EPOR-beta cR). Binding to the IRR induces rapid autophosphorylation of Janus kinase 2 (JAK2), which in turn triggers downstream STAT3 and Akt/protein kinase B survival cascades. In neuroinflammatory and diabetic neuropathy models, ARA-290 mitigates axonal degeneration, reduces Schwann cell apoptosis, suppresses pro-inflammatory macrophage M1 polarization, and promotes small nerve fiber regeneration.",
  "pentosan-polysulfate": "Pentosan Polysulfate Sodium (PPS) is a semi-synthetic sulfated polysaccharide macromolecule structurally analogous to physiological glycosaminoglycans (GAGs). In osteoarticular and connective tissue research, PPS acts as a chondroprotective, anti-inflammatory, and microvascular flow modulator. Mechanistically, PPS binds and inhibits a broad spectrum of destructive proteases, including aggrecanases (ADAMTS-4 and ADAMTS-5), matrix metalloproteinases (MMP-3, MMP-13), and elastases, preventing enzymatic degradation of cartilaginous aggrecan and type II collagen fibril networks. Concurrently, PPS stimulates hyaluronan synthesis by synovial fibroblasts and enhances proteoglycan secretion by articular chondrocytes. At the vascular level, PPS exhibits mild anticoagulant, fibrinolytic, and lipolytic activities, stimulating the release of tissue plasminogen activator (tPA) and clearing subchondral microvascular thrombi to restore subchondral bone perfusion.",

  // Category 2: Metabolic Signaling & Incretins
  "semaglutide": "Semaglutide is a long-acting synthetic GLP-1 (glucagon-like peptide-1) receptor agonist engineered with 94% amino acid sequence homology to native human GLP-1(7-37). Structural modifications include an Aib (alpha-aminoisobutyric acid) substitution at position 8 to confer resistance against dipeptidyl peptidase-4 (DPP-4) enzymatic degradation, and a lysine-26 derivatization with a hydrophilic spacer and a C18 fatty diacid chain. This lipophilic diacid facilitates high-affinity non-covalent binding to circulating albumin, extending in vivo plasma half-life to approximately 165 hours. Upon binding to the transmembrane GLP-1 receptor, semaglutide activates adenylate cyclase, elevating intracellular cyclic AMP (cAMP) and stimulating protein kinase A (PKA) and Epac2 pathways. In pancreatic beta-cells, this enhances glucose-dependent insulin secretion while concurrently suppressing glucagon release from alpha-cells. Centrally, it activates hypothalamic POMC/CART neurons and inhibits NPY/AgRP signaling, markedly delaying gastric motility and suppressing food intake in metabolic research models.",
  "tirzepatide": "Tirzepatide is a synthetic 39-amino-acid dual agonist peptide engineered to engage both the glucose-dependent insulinotropic polypeptide (GIP) receptor and the glucagon-like peptide-1 (GLP-1) receptor. Its chemical backbone is based on native GIP sequence modified with two non-coded aminoisobutyric acid (Aib) residues at positions 2 and 13, and a C20 fatty diacid moiety conjugated to lysine at position 20 via a gamma-glutamyl spacer. Pharmacodynamically, tirzepatide exhibits imbalanced agonism: it matches native GIP affinity at the GIP receptor while demonstrating approximately 5-fold lower affinity at the GLP-1 receptor compared to native GLP-1, thereby minimizing receptor desensitization and GI adverse kinetics. Co-activation of GIPR and GLP-1R exerts synergistic metabolic control: GIP signaling directly promotes white adipose tissue insulin sensitivity and lipolytic buffering, while GLP-1R activation suppresses glucagon secretion and slows gastric transit. In preclinical metabolic trials, this dual incretin mechanism produces superior glucose-lowering, beta-cell protection, and adiposity reduction compared to selective GLP-1 mono-agonists.",
  "retatrutide": "Retatrutide (LY3437943) is a synthetic 39-amino-acid peptide that functions as a single-molecule triple agonist targeting the GIP receptor, GLP-1 receptor, and glucagon receptor (GCGR). Its structural architecture incorporates an alpha-methyl-L-leucine residue at position 2, an Aib residue at position 20, and a C20 fatty diacid chain attached via a linker at position 17, providing an extended pharmacokinetic profile suitable for once-weekly laboratory protocols. In biochemical receptor binding assays, retatrutide demonstrates potent agonist activity across all three human receptors, displaying balanced potency at GIPR (EC50 ~0.07 nM), GLP-1R (EC50 ~0.78 nM), and GCGR (EC50 ~0.55 nM). The addition of glucagon receptor agonism to the dual incretin backbone directly stimulates hepatocyte lipid beta-oxidation, increases mitochondrial uncoupling, and elevates resting energy expenditure, while GIP and GLP-1 receptor co-agonism preserves glycemic stability and suppresses appetite. Preclinical rodent and non-human primate research demonstrates unmatched reductions in hepatic steatosis, fat mass, and body weight.",
  "cagrilintide": "Cagrilintide is a long-acting synthetic acylated analog of human amylin (islet amyloid polypeptide). Amylin is a 37-amino-acid neuroendocrine peptide co-secreted with insulin by pancreatic beta-cells that binds calcitonin receptor (CTR) cores complexed with receptor activity-modifying proteins (RAMP1, RAMP2, or RAMP3) to form high-affinity amylin receptors (AMYR1, AMYR2, AMYR3). Cagrilintide is engineered with strategic amino acid substitutions and a C20 fatty diacid side chain, resisting self-oligomerization into toxic amyloid fibrils while extending plasma half-life through albumin binding. Acting through AMYR complexes in the area postrema and nucleus of the solitary tract (NTS) in the hindbrain, cagrilintide induces robust homeostatic satiety signaling, delays gastric emptying, and blunts postprandial glucagon surges. When investigated in combination with GLP-1 receptor agonists, cagrilintide engages complementary non-overlapping neural circuits, delivering powerful synergistic metabolic regulation and fat mass reduction.",
  "mazdutide": "Mazdutide (IBI362) is a synthetic 29-amino-acid dual agonist targeting both the GLP-1 receptor and the glucagon receptor (GCGR). Modeled on mammalian oxyntomodulin, mazdutide features structural modifications including a C20 fatty diacid side chain that confers extended pharmacokinetic stability. By stimulating GLP-1R, mazdutide enhances glucose-dependent insulin secretion, slows gastrointestinal motility, and activates hypothalamic satiety pathways. Simultaneously, its glucagon receptor activity acts directly on hepatocytes to stimulate hepatic glycogenolysis and fatty acid beta-oxidation, increasing mitochondrial thermogenesis and overall energy expenditure. Preclinical and clinical models demonstrate that this balanced dual-receptor engagement reduces hepatic triglyceride content, improves lipid profiles, and drives substantial adiposity reduction without inducing sustained hyperglycemia or tachycardia.",
  "survodutide": "Survodutide (BI 456906) is a synthetic peptide dual agonist targeting the glucagon-like peptide-1 (GLP-1) receptor and the glucagon receptor (GCGR). Engineered with an acylated lipid side chain to ensure prolonged serum retention, survodutide delivers balanced and selective co-activation of hepatic and metabolic receptors. Activation of GCGR in liver tissue stimulates energy expenditure and enhances hepatic fatty acid clearance through mitochondrial uncoupling and beta-oxidation pathways, directly addressing non-alcoholic steatohepatitis (MASH/NASH) hallmarks. Concurrently, GLP-1 receptor engagement blunts glucagon-mediated hepatic glucose output, preserves insulin secretion from pancreatic beta-cells, and reduces food intake via central nervous system satiety circuits. Laboratory models show substantial reductions in hepatic steatosis, inflammatory fibrosis, and overall body mass.",
  "aod-9604": "AOD-9604 is a synthetic peptide fragment corresponding to the C-terminal region of human growth hormone (hGH amino acids 177–191), stabilized with an additional tyrosine residue at the N-terminus and an internal cyclic disulfide bridge (Cys182-Cys189). Originally developed to isolate the lipolytic actions of growth hormone from its somatotropic effects, AOD-9604 stimulates lipolysis and inhibits lipogenesis in adipocytes without binding the classical growth hormone receptor (GHR). Consequently, it does not stimulate IGF-1 synthesis, alter insulin sensitivity, or trigger cellular proliferation. Mechanistically, AOD-9604 upregulates beta-3 adrenergic receptor (beta3-AR) expression in adipose tissue and stimulates adipose triglyceride lipase (ATGL) and hormone-sensitive lipase (HSL) activity. In musculoskeletal research, AOD-9604 also displays chondrogenic and cartilage reparative properties, enhancing hyaline cartilage matrix proteoglycan deposition in articular chondrocyte cultures.",
  "5-amino-1mq": "5-Amino-1MQ (5-Amino-1-methylquinolinium) is a small-molecule, membrane-permeable selective inhibitor of nicotinamide N-methyltransferase (NNMT). NNMT is an intracellular enzyme predominantly expressed in adipose and liver tissues that catalyzes the transfer of a methyl group from S-adenosylmethionine (SAM) to nicotinamide (NAM), generating 1-methylnicotinamide (1-MNA). By inhibiting NNMT, 5-Amino-1MQ prevents the depletion of intracellular NAD+ and preserves S-adenosylmethionine (SAM) pools, reversing metabolic dysfunction associated with obesity and cellular senescence. Elevated NAD+ levels activate sirtuin-1 (SIRT1) and AMP-activated protein kinase (AMPK) signaling cascades, upregulating mitochondrial biogenesis, increasing cellular respiration, and promoting white-to-beige adipocyte phenotypic switching. Preclinical research demonstrates enhanced muscle contractile force, accelerated myofiber regeneration, and significant reductions in adiposity without central nervous system appetite suppression.",
  "tesofensine": "Tesofensine (NS2330) is a potent, centrally acting small-molecule triple monoamine reuptake inhibitor that blocks the presynaptic transporters for dopamine (DAT), norepinephrine (NET), and serotonin (SERT). Pharmacological binding assays demonstrate high-affinity transporter occupancy with an IC50 of approximately 6.5 nM for DAT, 1.7 nM for NET, and 11 nM for SERT. Mechanistically, tesofensine elevates synaptic concentrations of all three monoamines across critical hypothalamic nuclei, particularly within the lateral hypothalamus, arcuate nucleus, and ventral tegmental area. Increased dopaminergic and serotonergic tone modulates reward-driven feeding behavior, while noradrenergic elevation stimulates sympathetic nervous system activity and increases basal energy expenditure. Preclinical rodent and clinical translational studies show profound reductions in caloric intake, accelerated nocturnal fat oxidation, and sustained metabolic rate elevation.",
  "liraglutide": "Liraglutide is a synthetic long-acting human GLP-1 receptor agonist with 97% sequence homology to native GLP-1(7-37). It possesses a single amino acid substitution (Arg34 replacing Lys34) and a C16 palmitoyl fatty acid chain linked to lysine-26 via a gamma-glutamyl spacer. The palmitoyl moiety promotes self-association into heptameric structures at the injection site and non-covalent binding to serum albumin, protecting against renal filtration and providing an in vivo plasma half-life of approximately 13 hours. Upon GLP-1 receptor engagement, liraglutide stimulates cAMP-dependent PKA and Epac activation in pancreatic islets, enhancing glucose-dependent insulin secretion, blunting postprandial glucagon secretion, and delaying gastric emptying. Central nervous system signaling studies demonstrate that liraglutide crosses the blood-brain barrier at the circumventricular organs to stimulate anorexigenic POMC neurons and inhibit orexigenic NPY/AgRP networks.",

  // Category 3: Growth Hormone Axis
  "ipamorelin": "Ipamorelin is a synthetic pentapeptide (Aib-His-D-2-Nal-D-Phe-Lys-NH2) that acts as a highly selective growth hormone secretagogue receptor (GHS-R1a / ghrelin receptor) agonist. Unlike first-generation secretagogues such as GHRP-2 and GHRP-6, ipamorelin does not stimulate the release of adrenocorticotropic hormone (ACTH), cortisol, prolactin, or aldosterone, even at supra-physiological concentrations. Binding of ipamorelin to the pituitary GHS-R1a activates the Galphaq/11 protein cascade, stimulating phospholipase C (PLC) and generating inositol trisphosphate (IP3) and diacylglycerol (DAG). This induces rapid intracellular calcium mobilization from the endoplasmic reticulum, triggering pulsatile growth hormone vesicle exocytosis from pituitary somatotropes. The somatotropic pulse mimics natural physiological GH release, supporting nocturnal slow-wave sleep somatotropic surges, hepatic IGF-1 transcription, nitrogen retention, and lean tissue preservation without pituitary receptor desensitization.",
  "cjc-1295-no-dac": "CJC-1295 No DAC (also designated as Modified GRF 1-29) is a synthetic 29-amino-acid analog of growth hormone-releasing hormone (GHRH). It incorporates four strategic amino acid substitutions relative to native GHRH(1-29) (specifically D-Ala2, Gln8, Ala15, and Leu27), which protect the peptide against enzymatic cleavage by dipeptidyl peptidase-4 (DPP-4) and neutral endopeptidases. CJC-1295 No DAC binds directly to the GHRH receptor (GHRH-R) on pituitary somatotropes, activating the Galphas-protein coupled adenylate cyclase pathway and elevating cyclic AMP (cAMP) levels. When administered in laboratory models, it triggers physiological, episodic growth hormone release with a plasma half-life of approximately 30 minutes. In multi-peptide research, CJC-1295 No DAC demonstrates synergistic somatotrope stimulation when co-administered with GHS-R1a agonists (such as Ipamorelin), as simultaneous GHRH-R (cAMP/PKA) and GHS-R1a (PLC/IP3/Ca2+) stimulation produces a supra-additive growth hormone pulse.",
  "cjc-1295-with-dac": "CJC-1295 with DAC (Drug Affinity Complex) is an engineered long-acting growth hormone-releasing hormone (GHRH) tetra-substituted derivative conjugated to a maleimidopropionic acid (MPA) linker at its C-terminus. The reactive maleimide moiety covalently bioconjugates in situ to free cysteine-34 thiol groups on circulating serum albumin upon administration. Because serum albumin has a biological half-life of approximately 19–21 days, this bioconjugation shields the peptide from renal clearance and enzymatic degradation, extending the functional half-life of CJC-1295 with DAC to approximately 6 to 8 days. Continuous activation of pituitary GHRH receptors by CJC-1295 with DAC sustains elevated baseline and pulsatile growth hormone secretion, resulting in a continuous, non-fluctuating elevation of serum IGF-1 levels. It serves as an essential research tool for studying chronic somatotropic axis upregulation and muscle protein synthesis in extended mammalian models.",
  "tesamorelin": "Tesamorelin is a synthetic 44-amino-acid peptide consisting of the complete sequence of human growth hormone-releasing factor (GHRF 1-44) modified with a trans-3-hexenoyl fatty acid group attached to the N-terminal tyrosine residue. This lipophilic trans-3-hexenoyl modification significantly enhances enzymatic stability against DPP-4 degradation compared to native GHRF, extending its pharmacokinetic half-life. Tesamorelin selectively binds to and activates pituitary GHRH receptors, stimulating cyclic AMP synthesis and driving endogenous, pulsatile growth hormone synthesis and release. Increased somatotropic tone triggers hepatic IGF-1 expression and promotes lipolysis, specifically within metabolically active visceral adipose depots, while preserving subcutaneous fat. In translational research, tesamorelin is investigated for reducing visceral adiposity, mitigating hepatic steatosis, and improving metabolic parameters in lipid dystrophy models.",
  "sermorelin": "Sermorelin (GRF 1-29 amide) is a synthetic 29-amino-acid peptide representing the shortest functional N-terminal fragment of endogenous human growth hormone-releasing hormone (GHRH 1-44) that possesses full biological secretagogue activity. Sermorelin selectively binds to GHRH receptors located on pituitary somatotropes, activating adenylate cyclase and initiating the cyclic AMP-protein kinase A (PKA) signaling cascade. This triggers the synthesis and exocytosis of growth hormone in a natural pulsatile pattern governed by normal somatostatinergic negative feedback loops. Because sermorelin remains subject to endogenous somatostatin inhibition, it preserves the physiological regulatory architecture of the hypothalamic-pituitary somatotropic axis. In neuroendocrine research, sermorelin is widely used to evaluate pituitary somatotropic reserve and explore neurogenesis and cellular repair dynamics.",
  "ghrp-2": "GHRP-2 (Growth Hormone Releasing Peptide-2 / Pralmorelin) is a synthetic hexapeptide (D-Ala-D-beta-Nal-Ala-Trp-D-Phe-Lys-NH2) belonging to the growth hormone secretagogue class that functions as a potent agonist of the ghrelin/GHS-R1a receptor. GHRP-2 activates the Galphaq/PLC/IP3 signaling pathway, triggering robust intracellular calcium influx and inducing strong pulsatile growth hormone secretion from pituitary somatotropes. It exhibits high potency, producing greater peak growth hormone amplitude than GHRP-6 while causing significantly less orexigenic (appetite-stimulating) behavior. At standard analytical concentrations, GHRP-2 causes modest, transient elevations in prolactin and ACTH/cortisol that remain within physiological boundaries. In animal research models, GHRP-2 is used to promote lean mass accretion, stimulate chondrocyte proliferation, and support immune cell function.",
  "ghrp-6": "GHRP-6 (Growth Hormone Releasing Peptide-6) is a first-generation synthetic hexapeptide (His-D-Trp-Ala-Trp-D-Phe-Lys-NH2) that selectively targets and stimulates the growth hormone secretagogue receptor (GHS-R1a). In addition to stimulating pituitary growth hormone release via phospholipase C (PLC) and inositol trisphosphate (IP3) signaling, GHRP-6 acts as a potent ghrelin mimetic, binding hypothalamic GHS-R1a to stimulate orexigenic signaling pathways (NPY and AgRP activation), thereby markedly increasing appetite and food intake. In cytoprotective and ischemia-reperfusion research, GHRP-6 has been shown to exert robust cardioprotective, hepatoprotective, and neuroprotective properties independent of growth hormone secretion, mediated through the attenuation of pro-apoptotic caspase-3 cascades and preservation of mitochondrial membrane potential.",
  "hexarelin": "Hexarelin (Examorelin) is a synthetic hexapeptide secretagogue (His-D-2-Me-Trp-Ala-Trp-D-Phe-Lys-NH2) with the highest in vitro receptor affinity and growth hormone-releasing potency among the synthetic GHRP family. In addition to binding the pituitary and hypothalamic GHS-R1a receptor, hexarelin binds with high affinity to the CD36 scavenger receptor (thrombospondin receptor) present in cardiac myocytes, endothelial cells, and macrophages. CD36 binding by hexarelin activates cardioprotective and anti-apoptotic survival pathways, independent of growth hormone release, reducing myocardial infarct size and improving left ventricular hemodynamics in ischemic models. However, repetitive exposure to hexarelin produces noticeable somatotrope desensitization, requiring structured washout periods in analytical experimental protocols.",
  "mk-677": "MK-677 (Ibutamoren mesylate) is a potent, non-peptide, orally bioavailable agonist of the growth hormone secretagogue receptor (GHS-R1a). MK-677 mimics the functional activity of endogenous ghrelin, binding pituitary and hypothalamic GHS-R1a to stimulate pulsatile growth hormone release and sustained elevations in circulating insulin-like growth factor-1 (IGF-1) and IGFBP-3 levels without disrupting baseline cortisol rhythms. With an elimination half-life of approximately 24 hours, MK-677 maintains continuous 24-hour somatotropic axis elevation following single-dose administration. In laboratory models, MK-677 reverses diet-induced catabolism, increases bone mineral density via osteoblast stimulation, promotes lean tissue accretion, and increases rapid-eye-movement (REM) and slow-wave sleep duration.",

  // Category 4: Longevity & Cellular Health
  "mots-c": "MOTS-c (Mitochondrial Open Reading Frame of the 12S rRNA Type-c) is a 16-amino-acid mitochondrial-derived peptide (MDP) encoded by a short open reading frame within the mitochondrial 12S ribosomal RNA gene. Functioning as a mitochondrial hormone and retrograde signaling messenger, MOTS-c translocates from mitochondria to the nucleus under cellular metabolic stress. Mechanistically, MOTS-c directly regulates the folate-methionine metabolic cycle, depleting purine biosynthesis intermediates (specifically 5-aminoimidazole-4-carboxamide ribonucleotide / AICAR) and thereby robustly activating AMP-activated protein kinase (AMPK). AMPK activation upregulates glucose transporter 4 (GLUT4) translocation to cell membranes, enhances fatty acid beta-oxidation, and suppresses de novo lipogenesis in skeletal muscle. Research in metabolic and aging models shows that MOTS-c reverses diet-induced insulin resistance, preserves skeletal muscle mass, and promotes longevity phenotypes.",
  "ss-31": "SS-31 (Elamipretide / MTP-131) is a synthetic cell-permeable tetrapeptide (D-Arg-2'6'-Dmt-Lys-Phe-NH2) designed to target the inner mitochondrial membrane (IMM). Featuring an alternating aromatic-cationic structural motif, SS-31 selectively and reversibly binds with high affinity to cardiolipin, an essential phospholipid exclusive to the inner mitochondrial membrane. By electrostatic and hydrophobic interaction with cardiolipin, SS-31 stabilizes cristae curvature, optimizes electron transfer across complexes I, III, and IV of the electron transport chain (ETC), and prevents cardiolipin peroxidation by cytochrome c peroxidase complexes. This molecular stabilization diminishes mitochondrial reactive oxygen species (ROS) production, restores ATP synthesis efficiency, and prevents opening of the mitochondrial permeability transition pore (mPTP), mitigating apoptosis in ischemia-reperfusion, heart failure, and neurodegenerative disease models.",
  "epithalon": "Epithalon (Epithalone / Ala-Glu-Asp-Gly) is a synthetic tetrapeptide modeled after epithalamin, a natural peptide extract isolated from the bovine pineal gland. In molecular biogerontology research, Epithalon functions as an epigenetic transcriptional activator and telomerase upregulator. Mechanistically, Epithalon directly interacts with histone proteins and specific DNA sequences within the promoter region of the human telomerase reverse transcriptase (hTERT) gene, stimulating telomerase enzyme activity and promoting telomere elongation in somatic cells. Concurrently, Epithalon restores pineal gland sensitivity, upregulating nocturnal melatonin synthesis, normalizing neuroendocrine circadian rhythms, and stimulating endogenous antioxidant defense enzymes (superoxide dismutase and glutathione peroxidase). Extensive long-term animal studies demonstrate that Epithalon delays age-associated biomarker decline and extends mean maximum lifespan.",
  "foxo4-dri": "FOXO4-DRI (FOXO4 D-Retro-Inverso) is an engineered retro-inverso synthetic peptide designed to selectively disrupt the interaction between the Forkhead box O4 (FOXO4) transcription factor and the tumor suppressor p53 in senescent cells. In senescent cells, FOXO4 physically sequesters p53 in the nucleus, preventing it from translocating to mitochondria and initiating apoptosis, thereby maintaining senescence-associated secretory phenotype (SASP) viability. FOXO4-DRI is synthesized with all D-amino acids in reverse sequence, conferring complete resistance to intracellular proteases. By competitively binding the FOXO4-p53 interaction domain, FOXO4-DRI releases p53, allowing it to migrate to the cytoplasm and mitochondrial outer membrane, activating caspase-3/caspase-9 apoptosis cascades specifically in senescent cells while leaving non-senescent normal cells intact. In preclinical aging models, targeted senolysis with FOXO4-DRI restores tissue homeostasis, improves organ function, and enhances physiological fitness.",
  "humanin": "Humanin is an endogenous 24-amino-acid mitochondrial-derived peptide (MDP) encoded within the 16S ribosomal RNA gene in the mitochondrial genome. Humanin acts as a cytoprotective and anti-apoptotic signaling peptide across neural, vascular, and metabolic tissues. Mechanistically, Humanin binds directly to intracellular pro-apoptotic Bcl-2-associated X protein (Bax), preventing Bax translocation from the cytosol to the outer mitochondrial membrane and blocking cytochrome c release. Extracellularly, Humanin signals through a heterotrimeric cell-surface receptor complex composed of the IL-27 receptor subunit WSX-1, gp130, and the CNTF receptor alpha subunit (CNTFRalpha), as well as the G-protein coupled formyl peptide receptor-like-1 (FPRL-1). These receptor interactions activate STAT3, Akt, and ERK1/2 phosphorylation pathways, protecting neurons against amyloid-beta toxicity, mitigating vascular endothelial apoptosis, and preserving pancreatic beta-cell survival.",
  "nad-plus": "Nicotinamide Adenine Dinucleotide (NAD+) is a vital coenzyme and essential cosubstrate found in all living cells, central to cellular energy metabolism and cellular signaling. As an electron carrier, NAD+ alternates between its oxidized (NAD+) and reduced (NADH) states to drive oxidative phosphorylation, glycolysis, and the tricarboxylic acid (TCA) cycle. Beyond bioenergetics, NAD+ is an indispensable rate-limiting cosubstrate for three major enzyme classes: sirtuins (SIRT1-SIRT7, NAD+-dependent protein deacetylases), poly(ADP-ribose) polymerases (PARP enzymes, critical for genomic DNA repair), and cyclic ADP-ribose synthases (CD38/CD157, regulators of intracellular calcium signaling). Age-dependent decline in NAD+ pools compromises mitochondrial biogenesis, impairs nuclear-mitochondrial communication, and accelerates senescence. Analytical supplementation in research models restores mitochondrial respiration, improves mitochondrial unfolded protein response (UPRmt), and supports genomic stability.",
  "glutathione-reduced": "Glutathione (GSH / gamma-L-Glutamyl-L-cysteinylglycine) is the primary intracellular low-molecular-weight thiol and master endogenous antioxidant in mammalian cells. Synthesized via a two-step ATP-dependent enzymatic cascade involving glutamate-cysteine ligase (GCL) and glutathione synthetase (GS), GSH protects cells from oxidative and electrophilic stress. In its reduced form (GSH), it directly scavenges reactive oxygen species (ROS), including hydroxyl radicals and singlet oxygen, and acts as an essential cofactor for glutathione peroxidase (GPx) in reducing hydrogen peroxide and lipid hydroperoxides to water and harmless lipid alcohols, converting to glutathione disulfide (GSSG) in the process. GSSG is subsequently recycled back to GSH by glutathione reductase (GR) using NADPH. Furthermore, glutathione S-transferases (GSTs) conjugate GSH to xenobiotics and electrophilic metabolites for biliary and renal excretion, maintaining cellular redox equilibrium and mitochondrial cardiolipin integrity.",

  // Category 5: Cognitive & Neuroprotection
  "semax": "Semax is a synthetic heptapeptide (Met-Glu-His-Phe-Pro-Gly-Pro) derived from the N-terminal fragment of adrenocorticotropic hormone (ACTH 4-10) stabilized at its C-terminus with a Pro-Gly-Pro tripeptide. Crucially, Semax is completely devoid of hormonal corticotropic activity, exerting no stimulation on adrenal corticosteroid synthesis. In neurobiological research, Semax acts as a potent nootropic, neuroprotective, and neurorestorative signaling agent. Mechanistically, Semax rapidly upregulates the expression and synthesis of Brain-Derived Neurotrophic Factor (BDNF) and its high-affinity receptor TrkB in the hippocampus, frontal cortex, and striatum. This promotes neuroplasticity, dendritic spine formation, and long-term potentiation (LTP). Additionally, Semax modulates brain dopamine and serotonin turnover, stimulates nerve growth factor (NGF), and downregulates pro-inflammatory cytokines, protecting cerebral tissue in ischemic stroke, hypoxia, and neurodegenerative laboratory models.",
  "na-semax-amidate": "N-Acetyl Semax Amidate is an advanced synthetic analog of Semax engineered with dual chemical modifications: N-terminal acetylation (Ac-) and C-terminal amidation (-NH2). These end-cap modifications protect the peptide backbone against both aminopeptidase and carboxypeptidase enzymatic degradation, substantially extending its biological half-life and biological bioavailability across mucosal and blood-brain barrier interfaces compared to standard Semax. Pharmacodynamically, N-Acetyl Semax Amidate exhibits enhanced potency in upregulating hippocampal and cortical Brain-Derived Neurotrophic Factor (BDNF) and Nerve Growth Factor (NGF) mRNA and protein levels. It triggers TrkB receptor autophosphorylation and downstream MAPK/ERK and PI3K/Akt survival signaling cascades, enhancing memory consolidation, mental endurance, and neuronal survival under severe glutamate excitotoxicity and hypoxic stress.",
  "selank": "Selank is a synthetic heptapeptide (Thr-Lys-Pro-Arg-Pro-Gly-Pro) developed by fusing the endogenous immunomodulatory tetrapeptide tuftsin (TKPR) with a C-terminal Pro-Gly-Pro (PGP) tripeptide to ensure enzymatic stability and prolonged metabolic half-life. Selank acts as a synthetic anxiolytic and nootropic neuromodulator without inducing sedation, motor impairment, or withdrawal liability characteristic of classical GABAergic benzodiazepines. Mechanistically, Selank modulates allosteric binding at the GABA-A receptor complex, enhancing chloride ion conductance in the presence of GABA. Simultaneously, Selank increases the expression of Brain-Derived Neurotrophic Factor (BDNF) in hippocampal neurons, alters serotonin (5-HT) metabolism and turnover in the frontal cortex, and regulates the expression of interleukin-6 (IL-6) and other immune cytokines, establishing bidirectional neuro-immune homeostasis in stress and neuroinflammatory research models.",
  "na-selank-amidate": "N-Acetyl Selank Amidate is a chemically stabilized second-generation analog of the regulatory peptide Selank, incorporating N-terminal acetylation and C-terminal amidation end-caps. These covalent modifications shield the peptide from exopeptidase cleavage, significantly improving its enzymatic half-life, metabolic persistence, and central nervous system penetration. Like parent Selank, N-Acetyl Selank Amidate modulates the GABAergic neurotransmitter system via allosteric facilitation of GABA-A receptor complexes, attenuating stress-induced neuronal hyperactivity in the amygdala and locus coeruleus. Furthermore, it upregulates hippocampal BDNF gene expression, stabilizes monoaminergic neurotransmission (dopamine and serotonin), and suppresses pro-inflammatory cytokine expression. Laboratory models demonstrate enhanced anxiolytic efficacy, improved cognitive task focus, and heightened resilience against chronic environmental stress.",
  "cerebrolysin": "Cerebrolysin is a standardized, biologically active peptide preparation consisting of low-molecular-weight neuropeptides and free amino acids derived from purified porcine brain tissue. The peptide fraction contains active fragments structurally and functionally homologous to endogenous neurotrophic factors, including Brain-Derived Neurotrophic Factor (BDNF), Nerve Growth Factor (NGF), Glial Cell Line-Derived Neurotrophic Factor (GDNF), and Ciliary Neurotrophic Factor (CNTF). Pharmacologically, Cerebrolysin crosses the blood-brain barrier, binds neurotrophin receptors (TrkA, TrkB, Ret), and activates PI3K/Akt and MEK/ERK intracellular survival pathways. This neurotrophin-mimetic activity suppresses pro-apoptotic glycogen synthase kinase-3beta (GSK-3beta), inhibits calpain activation, decreases amyloid-beta and hyperphosphorylated tau accumulation, and stimulates neurogenesis, synaptic remodeling, and capillary angiogenesis in ischemic stroke and neurodegeneration models.",
  "p21": "P21 is a synthetic peptide derived from the active domain of Ciliary Neurotrophic Factor (CNTF amino acids 147–150, Ac-DGGL-NH2) engineered to be blood-brain barrier permeable and metabolically stable. Unlike full-length CNTF, P21 does not bind the CNTF cell-surface receptor complex (CNTFRalpha-gp130-LIFRbeta) and does not provoke neutralizing auto-antibodies or systemic inflammatory cachexia. Instead, P21 competitively inhibits the leukemia inhibitory factor (LIF) / bone morphogenetic protein (BMP) signaling pathway, effectively neutralizing endogenous neurogenesis inhibitors. By de-repressing neurogenic niches in the subgranular zone (SGZ) of the dentate gyrus and subventricular zone (SVZ), P21 stimulates endogenous adult neurogenesis, drives the proliferation of neural progenitor cells, and enhances synaptic plasticity and memory formation in neurodegenerative disease models.",
  "noopept": "Noopept (N-phenylacetyl-L-prolylglycine ethyl ester) is a synthetic dipeptide-derived nootropic agent chemically related to the racetam family but demonstrating upwards of 1,000-fold greater potency in animal behavioral assays. Upon administration, Noopept rapidly crosses the blood-brain barrier and is metabolized into the endogenous bioactive dipeptide cycloprolylglycine (CPG). Mechanistically, Noopept modulates central neurotransmission through multiple pathways: it acts as a positive allosteric modulator of AMPA and NMDA glutamate receptors, facilitating hippocampal long-term potentiation (LTP). Concurrently, Noopept stimulates the gene expression and synthesis of both Nerve Growth Factor (NGF) and Brain-Derived Neurotrophic Factor (BDNF) in the hippocampus and cerebral cortex. It also exhibits robust neuroprotective, antioxidant, and anti-inflammatory properties by attenuating glutamate excitotoxicity and lipid peroxidation.",
  "dihexa": "Dihexa (N-hexanoic-Tyr-Ile-(6)-aminohexanoic amide) is a synthetic, orally bioavailable oligopeptide drug candidate derived from angiotensin IV. In neuropharmacological research, Dihexa was engineered to bind Hepatocyte Growth Factor (HGF) with high affinity (Kd = 65 pM), stabilizing its active conformation and potently augmenting HGF dimerization and activation of its tyrosine kinase receptor, c-Met. Activation of the HGF/c-Met signaling axis triggers downstream PI3K/Akt, MAPK/ERK, and STAT3 cascades, driving robust synaptogenesis, spinogenesis, and dendritic arborization. In preclinical neurodegenerative models, Dihexa exhibits astonishing pro-cognitive and synaptic reparative potency—facilitating new functional synapse formation at concentrations orders of magnitude lower than Brain-Derived Neurotrophic Factor (BDNF)—making it a primary compound for researching synaptic recovery.",
  "dsip": "DSIP (Delta Sleep-Inducing Peptide) is an endogenous, naturally occurring 9-amino-acid regulatory neuropeptide (Trp-Ala-Gly-Gly-Asp-Ala-Ser-Gly-Glu) discovered in the dialysate of cerebral venous blood during induced slow-wave sleep in rabbits. Mechanistically, DSIP readily crosses the blood-brain barrier and modulates central neuroendocrine, circadian, and thermoregulatory rhythms. DSIP acts primarily on hypothalamic-pituitary circuits to induce and optimize delta-wave (0.5–4 Hz) slow-wave sleep without suppressing paradoxical (REM) sleep architecture. Furthermore, DSIP modulates hypothalamic corticotropin-releasing hormone (CRH) release, downregulating stress-induced adrenocorticotropic hormone (ACTH) and cortisol surges, stabilizing oxidative phosphorylation, and attenuating stress-induced monoamine depletion across the central nervous system.",

  // Category 6: Antimicrobial, Immune & Sexual Health
  "ll-37": "LL-37 is a 37-amino-acid amphipathic alpha-helical peptide representing the sole human member of the cathelicidin antimicrobial peptide family, cleaved enzymatically from the pro-protein hCAP-18. LL-37 exerts broad-spectrum antimicrobial activity against Gram-positive and Gram-negative bacteria, fungi, and enveloped viruses. Mechanistically, its positively charged residues electrostatically bind negatively charged bacterial phospholipid headgroups (such as phosphatidylglycerol and lipid A), inserting into and disrupting microbial membranes via the toroidal pore or carpet mechanism, leading to cell lysis. Beyond direct microbicidal activity, LL-37 is a potent immunomodulator and alarmin: it binds formyl peptide receptor-like 1 (FPRL-1/FPR2) and P2X7 purinergic receptors, chemoattracting neutrophils, monocytes, and T-cells to infection sites, neutralizes endotoxin (LPS), promotes re-epithelialization, and stimulates angiogenesis.",
  "thymosin-alpha-1": "Thymosin Alpha-1 (Talpha1) is an endogenous 28-amino-acid peptide (cleaved from prothymosin alpha) that plays an essential, master regulatory role in cell-mediated immunity and immune homeostasis. Mechanistically, Thymosin Alpha-1 signals through Toll-like receptors (TLR9 and TLR2) on dendritic cells and monocytes, activating the MyD88-dependent NF-κB and p38 MAPK pathways. This signaling stimulates the maturation of dendritic cells, enhances major histocompatibility complex (MHC Class I) expression on tumor or infected cells, and shifts the immune response toward a protective T-helper 1 (Th1) phenotype. Concurrently, it stimulates natural killer (NK) cell cytotoxic activity and activates indoleamine 2,3-dioxygenase (IDO), promoting regulatory T-cell (Treg) differentiation to prevent excessive autoimmune damage and restore immune balance.",
  "melanotan-1": "Melanotan-1 (Afamelanotide / [Nle4, D-Phe7]-alpha-MSH) is a synthetic 13-amino-acid linear peptide analog of endogenous alpha-melanocyte-stimulating hormone (alpha-MSH). It incorporates norleucine at position 4 and D-phenylalanine at position 7, conferring high resistance against proteolytic degradation and increasing its binding affinity for the melanocortin 1 receptor (MC1R) by more than 10-fold relative to native alpha-MSH. Selective activation of MC1R on epidermal melanocytes stimulates adenylate cyclase, elevating intracellular cyclic AMP (cAMP) and activating microphthalmia-associated transcription factor (MITF). MITF drives the expression of tyrosinase and related enzymes, stimulating eumelanin synthesis (photoprotective brown-black pigment) rather than pheomelanin (phototoxic red-yellow pigment). Because of its high MC1R selectivity, Melanotan-1 stimulates photoprotective melanogenesis without significantly engaging central MC4R sexual or appetite pathways.",
  "melanotan-2": "Melanotan-2 (MT-2) is a synthetic, cyclic lactam heptapeptide analog of alpha-MSH (Ac-Nle-cyclo[Asp-His-D-Phe-Arg-Trp-Lys]-NH2). Structural cyclization provides exceptional metabolic stability, resistance to endopeptidases, and broad cross-reactivity across the melanocortin receptor family, specifically targeting MC1R, MC3R, MC4R, and MC5R. While MC1R activation stimulates epidermal melanogenesis and eumelanin photoprotection, MT-2 readily crosses the blood-brain barrier to bind central melanocortin 4 receptors (MC4R) in the hypothalamus and sacral spinal parasympathetic centers. Activation of central MC4R pathways stimulates pro-erectile autonomic outflow, enhances sexual arousal and libido, and exerts potent anorexigenic appetite suppression. In translational research, MT-2 serves as an essential tool for evaluating melanocortinergic neuro-transmission, erectile physiology, and metabolic regulation.",
  "pt-141": "PT-141 (Bremelanotide) is a synthetic cyclic heptapeptide (Ac-Nle-cyclo[Asp-His-D-Phe-Arg-Trp-Lys]-OH) structurally derived from Melanotan-2 via C-terminal deamidation to a free carboxylic acid. This modification eliminates peripheral MC1R melanogenic activity while selectively preserving high-affinity agonism at central melanocortin 4 (MC4R) and melanocortin 3 (MC3R) receptors. Operating centrally within the brain, PT-141 acts on preoptic and hypothalamic MC4R neural circuits, stimulating dopamine release in the medial preoptic area (mPOA) and projecting down to spinal autonomic centers that govern sexual arousal and genital autonomic vascular inflow. Unlike phosphodiesterase-5 (PDE-5) inhibitors that act peripherally through vascular smooth muscle relaxation, PT-141 acts centrally to stimulate sexual desire and autonomic arousal, making it a critical research peptide in neurobiology.",
  "kisspeptin-10": "Kisspeptin-10 is an active, C-terminal 10-amino-acid decapeptide fragment (Tyr-Asn-Trp-Asn-Gly-Phe-Gly-Leu-Arg-Phe-NH2) of the human KISS1 gene product (metastin). Kisspeptin-10 is the minimal functional sequence required to bind with nanomolar affinity to the G-protein coupled Kisspeptin receptor (KISS1R / GPR54). Located on hypothalamic gonadotropin-releasing hormone (GnRH) neurons, KISS1R activation by Kisspeptin-10 stimulates the Galphaq/11-phospholipase C (PLC) pathway, initiating inositol trisphosphate (IP3) generation and intracellular calcium mobilization. This triggers high-frequency pulsatile release of GnRH into the hypophyseal portal circulation, which in turn drives pituitary secretion of luteinizing hormone (LH) and follicle-stimulating hormone (FSH). Kisspeptin-10 serves as the master neuroendocrine trigger of the hypothalamic-pituitary-gonadal (HPG) axis, controlling puberty onset, gametogenesis, and gonadal steroidogenesis.",
  "oxytocin": "Oxytocin is an endogenous cyclic nonapeptide (Cys-Tyr-Ile-Gln-Asn-Cys-Pro-Leu-Gly-NH2) containing an essential intramolecular disulfide bridge between cysteine residues 1 and 6. Synthesized primarily in the paraventricular and supraoptic nuclei of the hypothalamus and secreted from the posterior pituitary, oxytocin binds to the G-protein coupled oxytocin receptor (OXTR). OXTR coupling to Galphaq/11 activates phospholipase C (PLC), elevating intracellular calcium and driving smooth muscle contraction in reproductive and mammary tissues. Within the central nervous system, oxytocin acts as a powerful neuromodulator, binding OXTR in the amygdala, nucleus accumbens, and prefrontal cortex. This central signaling dampens amygdalar fear responses, attenuates hypothalamic-pituitary-adrenal (HPA) stress reactivity, promotes prosocial bonding and trust, and modulates maternal and affiliative behaviors in neurobiological models.",

  // Category 7: Multi-Peptide Blends
  "glow-blend": "The GLOW Formulation (GHK-Cu 50mg, BPC-157 10mg, TB-500 10mg) is a multi-pathway biological matrix research solution engineered to investigate synergistic extracellular matrix regeneration, microvascular angiogenesis, and tissue remodeling. Each constituent engages a distinct, non-overlapping regenerative cascade: GHK-Cu modulates gene transcription to upregulate collagen types I, III, and decorin while optimizing copper-dependent enzyme kinetics; BPC-157 stimulates VEGFR2 phosphorylation, eNOS activation, and FAK/paxillin focal adhesion signaling to direct endothelial cell migration; TB-500 sequesters G-actin to drive rapid lamellipodia formation, cellular extravasation, and matrix metalloproteinase (MMP-2/MMP-9) tissue remodeling. Co-administration in laboratory models demonstrates synchronized extracellular matrix repair and accelerated tissue restoration.",
  "klow-blend": "The KLOW Formulation (KPV 20mg, LL-37 10mg, GHK-Cu 40mg, BPC-157 10mg) is a multi-peptide formulation designed for investigating immune modulation, mucosal barrier defense, and concurrent tissue remodeling. KPV inhibits nuclear translocation of NF-κB, suppressing pro-inflammatory cytokine expression; LL-37 disrupts bacterial and microbial membrane integrity via toroidal pore formation while recruiting innate immune cells through FPRL-1 signaling; GHK-Cu resets cellular transcription toward a restorative phenotype and promotes collagen and glycosaminoglycan synthesis; BPC-157 upregulates tight junction proteins (ZO-1, occludin) and stimulates microvascular angiogenesis. In epithelial and soft tissue models, the KLOW blend provides a multi-target environment for studying concurrent pathogen defense and tissue healing.",
  "wolverine-blend": "The Wolverine Blend (BPC-157 5mg, TB-500 5mg) is a dual-peptide synergistic formulation designed to investigate accelerated musculoskeletal tissue repair and wound healing. The combination exploits the complementary mechanisms of BPC-157 and TB-500: BPC-157 stimulates the VEGFR2 and FAK-paxillin pathway, promoting local capillary angiogenesis and tenocyte collagen type I synthesis at the injury epicenter; TB-500 regulates actin cytoskeletal dynamics through G-actin sequestration, stimulating the motility and migration of fibroblasts and keratinocytes into the wound margins. Concurrently, both peptides downregulate inflammatory cytokines and attenuate pro-fibrotic signaling, allowing researchers to study coordinated tissue regeneration and tensile strength recovery.",
  "tri-heal-blend": "The Tri-Heal Formulation (BPC-157 5mg, TB-500 5mg, KPV 5mg) is an advanced triple-peptide matrix engineered for comprehensive tissue repair and inflammation research. In experimental models of severe connective tissue trauma, tissue regeneration is frequently impeded by persistent inflammatory signaling. The Tri-Heal formulation resolves this limitation by combining the pro-angiogenic and tenocyte-proliferative actions of BPC-157, the cell motility and actin-remodeling dynamics of TB-500, and the nuclear-targeted NF-κB inhibition of KPV. This synchronized multi-target approach suppresses inflammatory cytokines (TNF-alpha, IL-6) while simultaneously accelerating extracellular matrix deposition and neovascularization.",
  "cjc-ipam-blend": "The CJC-1295 / Ipamorelin Blend (CJC-1295 No DAC 5mg, Ipamorelin 5mg) is a synergistic dual growth hormone secretagogue formulation engineered to achieve supra-additive pituitary somatotrope stimulation. CJC-1295 (Modified GRF 1-29) acts as a GHRH receptor agonist, activating Galphas-adenylate cyclase and elevating intracellular cyclic AMP (cAMP) and PKA activity; Ipamorelin acts as a selective GHS-R1a (ghrelin receptor) agonist, activating Galphaq-phospholipase C and stimulating inositol trisphosphate (IP3)-mediated calcium mobilization. Simultaneous engagement of these two distinct signaling pathways produces a synergistic, amplification of physiological growth hormone pulsatility without elevating cortisol or prolactin.",
  "neuro-sync-blend": "The Neuro-Sync Formulation (Selank 5mg, Semax 5mg) is a dual-peptide neuro-cognitive research blend designed to evaluate synchronized nootropic, neuroprotective, and anxiolytic pathways in central nervous system models. Semax upregulates Brain-Derived Neurotrophic Factor (BDNF) and TrkB receptor expression in the hippocampus and cortex, stimulating long-term potentiation (LTP) and synaptic plasticity. Selank modulates allosteric GABA-A receptor conductance to mitigate stress-induced neuronal hyperactivity while balancing serotonin and dopamine turnover. Together, the Neuro-Sync blend provides a unified model for evaluating cognitive optimization and emotional stress resilience.",
}

const dir = path.resolve("apps/storefront/src/lib/data/compound-protocols")
const files = fs.readdirSync(dir).filter((f) => f.startsWith("category-") && f.endsWith(".ts"))

let totalInjected = 0

for (const file of files) {
  const filePath = path.join(dir, file)
  let content = fs.readFileSync(filePath, "utf8")
  let fileInjected = 0

  content = content.replace(
    /id:\s*"([a-z0-9-]+)",([\s\S]*?subtitle:\s*"([^"]+)",)/g,
    (match, id, middle, subtitle) => {
      const monograph = MONOGRAPHS[id]
      if (!monograph) {
        console.warn(`[WARN] No monograph for id: ${id} in ${file}`)
        return match
      }

      if (middle.includes("longDescription:")) {
        return match
      }

      fileInjected++
      totalInjected++
      const escaped = monograph.replace(/"/g, '\\"')
      return `id: "${id}",${middle}\n    longDescription:\n      "${escaped}",`
    }
  )

  fs.writeFileSync(filePath, content, "utf8")
  console.log(`[OK] ${file}: injected ${fileInjected} monographs`)
}

console.log(`\nSuccessfully injected ${totalInjected} monographs across ${files.length} categories.`)
